fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut lo: usize = 0;
    let mut hi: usize = arr.len();

    // Binary search for the first position where arr[pos] >= target
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    // lo is now the smallest index such that arr[lo] >= target (or arr.len())
    if lo < arr.len() && arr[lo] == target {
        Some(lo)
    } else {
        None
    }
}

